#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#include "../hwt1d-cuda/kernel.cu"
#include "../hwt1d-cuda/reference.cu"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=16384,repeats=argc>1?atoi(argv[1]):20;std::vector<float>input(n),expected(n),got(n);srand(2);for(int i=0;i<n;i++)input[i]=rand()%10;calApproxFinalOnHost(input.data(),expected.data(),n);float *data,*out,*partial;for(auto p:{&data,&out,&partial})CK(cudaMalloc(p,n*4));auto launch=[&](){dwtHaar1D<<<32,256,512*4>>>(data,out,partial,14,n,0,9);CK(cudaMemcpyAsync(data,partial,32*4,cudaMemcpyDeviceToDevice));dwtHaar1D<<<1,16,32*4>>>(data,out,partial,5,32,9,9);CK(cudaMemcpyAsync(out,partial,4,cudaMemcpyDeviceToDevice));};CK(cudaMemcpy(data,input.data(),n*4,cudaMemcpyHostToDevice));launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double elapsed=0;for(int rep=0;rep<repeats;rep++){CK(cudaMemcpy(data,input.data(),n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();launch();CK(cudaDeviceSynchronize());elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;}CK(cudaMemcpy(got.data(),out,n*4,cudaMemcpyDeviceToHost));float ma=0,mr=0;bool ok=true;for(int i=0;i<n;i++){float e=fabsf(got[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(got[i])&&e<=.1f;}all&=ok;char file[100];sprintf(file,"hwt1d_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),4,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"full_device_transform_including_normalization_and_required_d2d_copies\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",n,ma,mr,repeats,file,n);}for(auto p:{data,out,partial})CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
